#!/usr/bin/env python3
"""Check HTML well-formedness using html.parser.HTMLParser."""

import sys
from html.parser import HTMLParser

VOID_ELEMENTS = frozenset([
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
])

FILES = [
    "index.html",
    "blog.html",
    "publications.html",
    "posts/interpretable-deep-learning.html",
    "posts/ml-and-single-cell-genomics.html",
    "posts/scaling-gnns-connectomics.html",
]


class WellFormedChecker(HTMLParser):
    def __init__(self, filename):
        super().__init__()
        self.filename = filename
        self.stack = []          # list of (tag, line)
        self.errors = []

    def handle_starttag(self, tag, attrs):
        self.stack.append((tag, self.getpos()[0]))

    def handle_endtag(self, tag):
        tag_lower = tag.lower()
        # Walk the stack backwards to find a matching open tag
        found = None
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0].lower() == tag_lower:
                found = i
                break
        if found is None:
            self.errors.append(
                f"STRAY {self.filename} line {self.getpos()[0]}: </{tag}>"
            )
            return
        # If the matching tag is not at the top, everything above it is a mismatch
        if found != len(self.stack) - 1:
            top_tag = self.stack[-1][0]
            self.errors.append(
                f"MISMATCH {self.filename} line {self.getpos()[0]}: </{tag}> while {top_tag} is open"
            )
            # Pop the mismatched top tag so we can continue checking
            self.stack.pop()
            # Now retry: the current end tag should match the new top
            self.handle_endtag(tag)
        else:
            self.stack.pop()

    def handle_startendtag(self, tag, attrs):
        # Self-closing like <br /> — do nothing
        pass

    def handle_comment(self, data):
        pass

    def handle_decl(self, decl):
        pass

    def handle_pi(self, data):
        pass

    def unknown_decl(self, data):
        pass


def main():
    any_problem = False
    for filepath in FILES:
        try:
            with open(filepath, "r", encoding="utf-8") as f:
                content = f.read()
        except FileNotFoundError:
            print(f"ERROR {filepath}: file not found")
            any_problem = True
            continue

        parser = WellFormedChecker(filepath)
        try:
            parser.feed(content)
        except Exception as e:
            print(f"PARSE_ERROR {filepath}: {e}")
            any_problem = True
            continue

        if parser.errors:
            for err in parser.errors:
                print(err)
            any_problem = True
        elif parser.stack:
            # Tags still on the stack at end of document
            unclosed = ", ".join(f"{tag}" for tag, _ in parser.stack)
            print(f"UNCLOSED {filepath}: {unclosed}")
            any_problem = True
        else:
            print(f"OK {filepath}")

    sys.exit(1 if any_problem else 0)


if __name__ == "__main__":
    main()
